#define LOG_LEVEL CONFIG_KERNEL_LOG_LEVEL
#include <zephyr/logging/log.h>
LOG_MODULE_DECLARE(os, LOG_LEVEL);

static void work_q_main(void *p1, void *p2, void *p3)
{
	struct k_work_q *work_q = p1;
	struct k_work *work;

	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	while (true) {
		work = k_queue_get(&work_q->queue, K_FOREVER);
		if (work == NULL) {
			/* This can happen if the queue is drained. */
			continue;
		}

		if (work->handler != NULL) {
			work->handler(work);
		}
	}
}

void k_work_q_init(struct k_work_q *work_q)
{
	__ASSERT_NO_MSG(work_q != NULL);

	k_queue_init(&work_q->queue);
	k_thread_stack_define(work_q->stack, work_q->stack_size);
	work_q->thread = (struct k_thread){0};
	work_q->thread_options = 0;
	work_q->thread_priority = 0;
	work_q->thread_name = NULL;
}

int k_work_q_start(struct k_work_q *work_q, k_thread_stack_t *stack,
		   size_t stack_size, int prio, uint32_t options,
		   const char *thread_name)
{
	__ASSERT_NO_MSG(work_q != NULL);
	__ASSERT_NO_MSG(stack != NULL);
	__ASSERT_NO_MSG(stack_size > 0);

	work_q->stack = stack;
	work_q->stack_size = stack_size;
	work_q->thread_options = options;
	work_q->thread_priority = prio;
	work_q->thread_name = thread_name;

	k_thread_create(&work_q->thread, work_q->stack, work_q->stack_size,
			work_q_main, work_q, NULL, NULL,
			work_q->thread_priority, work_q->thread_options,
			K_FOREVER);
	k_thread_name_set(&work_q->thread, work_q->thread_name);
	k_thread_start(&work_q->thread);

	return 0;
}

void k_work_init(struct k_work *work, k_work_handler_t handler)
{
	__ASSERT_NO_MSG(work != NULL);
	__ASSERT_NO_MSG(handler != NULL);

	memset(work, 0, sizeof(struct k_work));
	work->handler = handler;
	atomic_set(&work->flags, 0);
}

void k_work_submit_to_queue(struct k_work_q *work_q, struct k_work *work)
{
	__ASSERT_NO_MSG(work_q != NULL);
	__ASSERT_NO_MSG(work != NULL);

	if (atomic_test_and_set_bit(&work->flags, K_WORK_STATE_PENDING)) {
		return;
	}

	k_queue_put(&work_q->queue, work);
}

void k_work_submit(struct k_work *work)
{
	k_work_submit_to_queue(k_sys_work_q_get(), work);
}

void k_work_flush_q(struct k_work_q *work_q, struct k_work *work,
		    k_work_flush_callback_t flush_cb)
{
	__ASSERT_NO_MSG(work_q != NULL);
	__ASSERT_NO_MSG(work != NULL);

	if (!atomic_test_bit(&work->flags, K_WORK_STATE_PENDING)) {
		/* Work is not pending, so it's either already executed or
		 * never submitted.
		 */
		return;
	}

	/* Wait until the work is no longer pending. */
	k_work_wait(work, K_FOREVER);

	if (flush_cb != NULL) {
		flush_cb(work);
	}
}

void k_work_flush(struct k_work *work, k_work_flush_callback_t flush_cb)
{
	k_work_flush_q(k_sys_work_q_get(), work, flush_cb);
}

void k_work_wait(struct k_work *work, k_timeout_t timeout)
{
	__ASSERT_NO_MSG(work != NULL);

	if (!atomic_test_bit(&work->flags, K_WORK_STATE_PENDING)) {
		/* Work is not pending, so it's either already executed or
		 * never submitted.
		 */
		return;
	}

	k_sem_take(&work->sem, timeout);
}

void k_work_cancel_sync(struct k_work *work, struct k_work_sync *sync)
{
	__ASSERT_NO_MSG(work != NULL);
	__ASSERT_NO_MSG(sync != NULL);

	if (!atomic_test_bit(&work->flags, K_WORK_STATE_PENDING)) {
		/* Work is not pending, so it's either already executed or
		 * never submitted.
		 */
		return;
	}

	k_sem_init(&sync->sem, 0, 1);
	work->sync = sync;

	/* Wait until the work is no longer pending. */
	k_work_wait(work, K_FOREVER);
}

void k_work_drain(struct k_work_q *work_q)
{
	__ASSERT_NO_MSG(work_q != NULL);

	k_queue_drain(&work_q->queue);
}

void k_work_loop_init(struct k_work_loop *work_loop, k_work_handler_t handler)
{
	__ASSERT_NO_MSG(work_loop != NULL);
	__ASSERT_NO_MSG(handler != NULL);

	k_work_init(&work_loop->work, handler);
	k_sem_init(&work_loop->sem, 0, 1);
}

void k_work_loop_submit_to_queue(struct k_work_q *work_q,
				 struct k_work_loop *work_loop)
{
	__ASSERT_NO_MSG(work_q != NULL);
	__ASSERT_NO_MSG(work_loop != NULL);

	if (atomic_test_and_set_bit(&work_loop->work.flags,
				    K_WORK_STATE_PENDING)) {
		return;
	}

	k_queue_put(&work_q->queue, &work_loop->work);
}

void k_work_loop_submit(struct k_work_loop *work_loop)
{
	k_work_loop_submit_to_queue(k_sys_work_q_get(), work_loop);
}

void k_work_loop_start(struct k_work_loop *work_loop)
{
	__ASSERT_NO_MSG(work_loop != NULL);

	k_sem_give(&work_loop->sem);
}

void k_work_loop_stop(struct k_work_loop *work_loop)
{
	__ASSERT_NO_MSG(work_loop != NULL);

	k_sem_take(&work_loop->sem, K_FOREVER);
}

void k_work_delayable_init(struct k_work_delayable *dwork,
			   k_work_handler_t handler)
{
	__ASSERT_NO_MSG(dwork != NULL);
	__ASSERT_NO_MSG(handler != NULL);

	k_work_init(&dwork->work, handler);
	k_timer_init(&dwork->timer, z_work_delayable_handler, NULL);
	k_timer_user_data_set(&dwork->timer, dwork);
}

int k_work_delayable_submit_to_queue(struct k_work_q *work_q,
				     struct k_work_delayable *dwork,
				     k_timeout_t delay)
{
	__ASSERT_NO_MSG(work_q != NULL);
	__ASSERT_NO_MSG(dwork != NULL);

	if (atomic_test_and_set_bit(&dwork->work.flags, K_WORK_STATE_PENDING)) {
		return -EALREADY;
	}

	dwork->work_q = work_q;
	k_timer_start(&dwork->timer, delay, K_NO_WAIT);

	return 0;
}

int k_work_delayable_submit(struct k_work_delayable *dwork, k_timeout_t delay)
{
	return k_work_delayable_submit_to_queue(k_sys_work_q_get(), dwork, delay);
}

int k_work_delayable_cancel(struct k_work_delayable *dwork)
{
	__ASSERT_NO_MSG(dwork != NULL);

	int ret = k_timer_stop(&dwork->timer);

	if (ret == 0) {
		/* Timer was stopped, so work was not yet submitted or was
		 * already submitted and handled. Clear pending flag if it was
		 * pending.
		 */
		atomic_clear_bit(&dwork->work.flags, K_WORK_STATE_PENDING);
	}

	return ret;
}

int k_work_delayable_cancel_sync(struct k_work_delayable *dwork,
				 struct k_work_sync *sync)
{
	__ASSERT_NO_MSG(dwork != NULL);
	__ASSERT_NO_MSG(sync != NULL);

	int ret = k_work_delayable_cancel(dwork);

	if (ret == 0) {
		/* Work was not pending, so nothing to wait for. */
		return 0;
	}

	k_sem_init(&sync->sem, 0, 1);
	dwork->work.sync = sync;

	/* Wait until the work is no longer pending. */
	k_work_wait(&dwork->work, K_FOREVER);

	return 0;
}

bool k_work_delayable_is_pending(struct k_work_delayable *dwork)
{
	__ASSERT_NO_MSG(dwork != NULL);

	return atomic_test_bit(&dwork->work.flags, K_WORK_STATE_PENDING);
}

struct k_work_q *k_work_delayable_current_work_q(struct k_work_delayable *dwork)
{
	__ASSERT_NO_MSG(dwork != NULL);

	return dwork->work_q;
}

void z_work_delayable_handler(struct k_timer *timer)
{
	struct k_work_delayable *dwork = k_timer_user_data_get(timer);

	k_queue_put(&dwork->work_q->queue, &dwork->work);
}

#ifdef CONFIG_SYS_CLOCK_EXISTS
static K_WORK_DELAYABLE_DEFINE(sys_work_delayable, NULL);

void k_work_schedule(struct k_work *work, k_timeout_t delay)
{
	__ASSERT_NO_MSG(work != NULL);

	k_work_delayable_init(&sys_work_delayable, work->handler);
	k_work_delayable_submit(&sys_work_delayable, delay);
}

void k_work_cancel(struct k_work *work)
{
	__ASSERT_NO_MSG(work != NULL);

	k_work_delayable_cancel(&sys_work_delayable);
}
#endif /* CONFIG_SYS_CLOCK_EXISTS */

